public class TransactionEngine {
    public String process(String instr, Map<String, Account> accs, List<String> log, Map<String, String> txs, FeeService fs, int ctr) {
        if (instr == null || instr.isBlank()) { log.add(String.format("%03d  ??? ????-??-?? REJECTED BAD_INSTRUCTION", ctr)); return "REJECTED BAD_INSTRUCTION: empty instruction"; }
        String[] p = instr.split("\\|");
        String verb = p[0];
        if (verb.equals("DEPOSIT")) return new Processor().deposit(p, accs, log, fs, ctr);
        if (verb.equals("WITHDRAW")) return new Processor().withdraw(p, accs, log, fs, ctr);
        if (verb.equals("TRANSFER")) return new Processor().transfer(p, accs, log, fs, ctr);
        if (verb.equals("REVERSE")) return new Processor().reverse(p, accs, log, txs, fs, ctr);
        log.add(String.format("%03d  %s ????-??-?? REJECTED BAD_INSTRUCTION", ctr, verb));
        return "REJECTED BAD_INSTRUCTION: unknown verb " + verb;
    }
}
