public class ReportService {
    public String generate(String date, List<String> log, FeeService fs) {
        long ok = log.stream().filter(s -> s.contains(date) && s.contains("OK")).count();
        long rej = log.stream().filter(s -> s.contains(date) && s.contains("REJECTED")).count();
        if (ok == 0 && rej == 0) return "REPORT " + date + "\nok: 0\nrejected: 0\nfees: none";
        return "REPORT " + date + "\nok: " + ok + "\nrejected: " + rej + "\nfees: 0.00 PLN";
